/* ---------------------------------------------------------------------------
 * osborne1-cpm : sound — 8253 PIT / PC-speaker tone generator
 *
 * One square-wave channel, gated by the speaker port. Everything the era made
 * noise with is built from it: the 2600 Hz continuous tone and the three blips
 * of Pong. Rendering produces 8-bit unsigned PCM so a front end can drive a
 * real audio device and a tool can drop a .wav on disk for inspection.
 *
 * The speaker is one bit: silent (128) or full-scale (255/0). A square wave is
 * generated by toggling that bit once per half period.
 * ------------------------------------------------------------------------- */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>

#include "sound.h"

#define PCM_SILENCE 128
#define PCM_HIGH 255
#define PCM_LOW 0

struct sound
{
    int rate;     /* samples per second for render() */
    int active;   /* speaker gated on?               */
    double freq;  /* tone frequency in Hz            */
    double phase; /* 0..1 position within the period */
};

/* --- lifecycle --------------------------------------------------------- */

struct sound *sound_create(void)
{
    struct sound *s = calloc(1, sizeof(*s));

    if (s == NULL)
        return NULL;
    s->rate = SOUND_RATE_DEFAULT;
    s->active = 0;
    s->freq = 0.0;
    s->phase = 0.0;
    return s;
}

void sound_destroy(struct sound *s) { free(s); }

void sound_reset(struct sound *s)
{
    if (s == NULL)
        return;
    s->active = 0;
    s->freq = 0.0;
    s->phase = 0.0;
}

/* --- the speaker port -------------------------------------------------- */

int sound_on(struct sound *s, double freq_hz)
{
    if (s == NULL)
        return OSB_EBADARG;
    if (freq_hz < SOUND_MIN_HZ || freq_hz > SOUND_MAX_HZ)
        return OSB_EBADARG;
    s->freq = freq_hz;
    s->active = 1;
    /* restart the waveform so repeated blips sound the same */
    s->phase = 0.0;
    return OSB_OK;
}

void sound_off(struct sound *s)
{
    if (s == NULL)
        return;
    s->active = 0;
    s->phase = 0.0;
}

int sound_active(const struct sound *s) { return s ? s->active : 0; }
double sound_freq(const struct sound *s) { return s ? s->freq : 0.0; }

int sound_set_rate(struct sound *s, int rate)
{
    if (s == NULL || rate < 1000 || rate > 192000)
        return OSB_EBADARG;
    s->rate = rate;
    return OSB_OK;
}

int sound_rate(const struct sound *s) { return s ? s->rate : SOUND_RATE_DEFAULT; }

/* --- rendering --------------------------------------------------------- */

int sound_render(struct sound *s, u8 *buf, int nsamples)
{
    int i;

    if (s == NULL || buf == NULL || nsamples < 0)
        return OSB_EBADARG;
    if (nsamples > SOUND_MAX_SAMPLES)
        nsamples = SOUND_MAX_SAMPLES;

    for (i = 0; i < nsamples; i++)
    {
        if (!s->active || s->freq <= 0.0)
        {
            buf[i] = PCM_SILENCE;
            continue;
        }
        /* advance the phase by one sample period, wrapped to [0,1) */
        s->phase += s->freq / (double)s->rate;
        if (s->phase >= 1.0)
            s->phase -= floor(s->phase);
        buf[i] = s->phase < 0.5 ? PCM_HIGH : PCM_LOW;
    }
    return nsamples;
}

int sound_tone_pcm(u8 *buf, int max_samples, int rate, double freq_hz, int ms)
{
    int n, i;
    double phase = 0.0;

    if (buf == NULL || max_samples <= 0 || rate <= 0 || ms <= 0)
        return OSB_EBADARG;
    if (freq_hz < SOUND_MIN_HZ || freq_hz > SOUND_MAX_HZ)
        return OSB_EBADARG;

    n = (int)(((long)rate * ms) / 1000);
    if (n > max_samples)
        n = max_samples;

    for (i = 0; i < n; i++)
    {
        phase += freq_hz / (double)rate;
        if (phase >= 1.0)
            phase -= floor(phase);
        buf[i] = phase < 0.5 ? PCM_HIGH : PCM_LOW;
    }
    return n;
}

/* --- effects ----------------------------------------------------------- */

int sound_2600(struct sound *s, u8 *buf, int max_samples, int ms)
{
    if (s == NULL)
        return OSB_EBADARG;
    sound_on(s, SOUND_TONE_2600);
    return sound_tone_pcm(buf, max_samples, s->rate, SOUND_TONE_2600, ms);
}

double sound_pong_freq(int event)
{
    switch (event)
    {
    case PONG_PADDLE:
        return PONG_FREQ_PADDLE;
    case PONG_WALL:
        return PONG_FREQ_WALL;
    case PONG_SCORE:
        return PONG_FREQ_SCORE;
    case PONG_START:
        return SOUND_TONE_BEEP;
    case PONG_GAME_OVER:
        return PONG_FREQ_SCORE;
    }
    return PONG_FREQ_PADDLE;
}

int sound_pong_ms(int event)
{
    switch (event)
    {
    case PONG_PADDLE:
        return 30; /* sharp click on the return */
    case PONG_WALL:
        return 30;
    case PONG_SCORE:
        return 250; /* long low buzz when a point is lost */
    case PONG_START:
        return 120;
    case PONG_GAME_OVER:
        return 600;
    }
    return 30;
}

int sound_pong(struct sound *s, int event, u8 *buf, int max_samples)
{
    double f;
    int ms;

    if (s == NULL || buf == NULL)
        return OSB_EBADARG;

    f = sound_pong_freq(event);
    ms = sound_pong_ms(event);

    /* A missed ball is not a tone but a falling thunk; render three short
     * descending steps and leave the speaker off, the way the cabinet did. */
    if (event == PONG_SCORE || event == PONG_GAME_OVER)
    {
        int steps = event == PONG_GAME_OVER ? 3 : 1;
        int step_ms = ms / steps;
        int wrote = 0, i;

        sound_off(s);
        for (i = 0; i < steps; i++)
        {
            double fi = f * (1.0 + 0.35 * i); /* climb for the game-over jingle */
            int n = sound_tone_pcm(buf + wrote, max_samples - wrote, s->rate,
                                   fi, step_ms);
            if (n < 0)
                break;
            wrote += n;
        }
        return wrote;
    }

    sound_on(s, f);
    return sound_tone_pcm(buf, max_samples, s->rate, f, ms);
}

/* --- printer effect ---------------------------------------------------- */

/* A tiny mixer: the printer effect is a sequence of very short one-shot blips
 * separated by gaps of silence, so it cannot reuse sound_tone_pcm()'s single
 * contiguous run. `cursor` and `used` track where the next blip lands. */
struct pcm_buf
{
    u8 *buf;
    int max;
    int used;
};

static int pcm_avail(const struct pcm_buf *b) { return b->max - b->used; }

static int pcm_put(struct pcm_buf *b, int n)
{
    if (b->used + n > b->max)
        n = b->max - b->used;
    if (n < 0)
        n = 0;
    b->used += n;
    return n;
}

static int pcm_silence(struct pcm_buf *b, int n)
{
    if (b->used + n > b->max)
        n = b->max - b->used;
    if (n <= 0)
        return 0;
    memset(b->buf + b->used, PCM_SILENCE, (size_t)n);
    b->used += n;
    return n;
}

double sound_printer_freq(int event)
{
    switch (event)
    {
    case PRINTER_READY:
        return PRINTER_FREQ_READY;
    case PRINTER_DOT:
        return PRINTER_FREQ_TICK;
    case PRINTER_LINE:
        return PRINTER_FREQ_RETURN;
    case PRINTER_FEED:
        return PRINTER_FREQ_FEED;
    case PRINTER_BELL:
        return PRINTER_FREQ_BELL;
    case PRINTER_JOB:
        return PRINTER_FREQ_TICK;
    }
    return PRINTER_FREQ_TICK;
}

int sound_printer_ms(int event)
{
    switch (event)
    {
    case PRINTER_READY:
        return 80;
    case PRINTER_DOT:
        return 8; /* the head's click as it passes one column */
    case PRINTER_LINE:
        return 60;
    case PRINTER_FEED:
        return 50;
    case PRINTER_BELL:
        return 150;
    case PRINTER_JOB:
        return 0; /* length depends on the character rate */
    }
    return 8;
}

/* One short blip at `freq`, `on_ms` long, preceded by `gap_ms` of silence. */
static int printer_blip(struct pcm_buf *b, int rate, double freq,
                        int on_ms, int gap_ms)
{
    int n;

    if (gap_ms > 0)
        pcm_silence(b, rate * gap_ms / 1000);
    n = sound_tone_pcm(b->buf + b->used, pcm_avail(b), rate, freq, on_ms);
    if (n < 0)
        return n;
    pcm_put(b, n);
    return n;
}

/* One line of text: a rattle of character ticks, then a carriage return. */
static int printer_print_line(struct pcm_buf *b, int rate, int cols, int cps)
{
    int i;
    int gap = 1000 / (cps > 0 ? cps : PRINTER_CPS_DEFAULT);
    int on = gap < 10 ? gap : 10; /* click must be shorter than its gap */

    if (on < 1)
        on = 1;
    for (i = 0; i < cols; i++)
        printer_blip(b, rate, PRINTER_FREQ_TICK, on, gap - on);
    /* the carriage sweeps home a little slower than it typed */
    return printer_blip(b, rate, PRINTER_FREQ_RETURN, 45, 30);
}

int sound_printer(struct sound *s, int event, u8 *buf, int max_samples,
                  int speed)
{
    struct pcm_buf b;
    int rate;

    if (s == NULL || buf == NULL || max_samples <= 0)
        return OSB_EBADARG;

    rate = s->rate;
    b.buf = buf;
    b.max = max_samples;
    b.used = 0;

    /* The printer's one-shot blips all leave the speaker off, the way a
     * mechanical print head has no held tone. */
    sound_off(s);

    switch (event)
    {
    case PRINTER_READY:
        /* a rising two-note "online" chirp */
        printer_blip(&b, rate, PRINTER_FREQ_READY_LO, 70, 0);
        printer_blip(&b, rate, PRINTER_FREQ_READY, 80, 25);
        break;

    case PRINTER_DOT:
        printer_blip(&b, rate, PRINTER_FREQ_TICK, 8, 0);
        break;

    case PRINTER_LINE:
        printer_print_line(&b, rate, 72, speed > 0 ? speed : PRINTER_CPS_DEFAULT);
        break;

    case PRINTER_FEED:
        /* the tractor stepping the paper one line */
        printer_blip(&b, rate, PRINTER_FREQ_FEED, 60, 0);
        break;

    case PRINTER_BELL:
        /* the done-bell, rung twice */
        printer_blip(&b, rate, PRINTER_FREQ_BELL, 150, 0);
        printer_blip(&b, rate, PRINTER_FREQ_BELL, 110, 90);
        break;

    case PRINTER_JOB:
    {
        /* three pages: header, body, trailer; a feed between each */
        int page;

        for (page = 0; page < 3; page++)
        {
            printer_print_line(&b, rate, 72, PRINTER_CPS_DEFAULT);
            printer_print_line(&b, rate, 72, PRINTER_CPS_DEFAULT);
            printer_blip(&b, rate, PRINTER_FREQ_FEED, 50, 20);
        }
        printer_blip(&b, rate, PRINTER_FREQ_BELL, 150, 60);
        break;
    }

    default:
        return OSB_EBADARG;
    }

    return b.used;
}

/* --- output ------------------------------------------------------------ */

static void put_u32le(FILE *f, u32 v)
{
    fputc((int)(v & 0xff), f);
    fputc((int)((v >> 8) & 0xff), f);
    fputc((int)((v >> 16) & 0xff), f);
    fputc((int)((v >> 24) & 0xff), f);
}

static void put_u16le(FILE *f, u16 v)
{
    fputc((int)(v & 0xff), f);
    fputc((int)((v >> 8) & 0xff), f);
}

int sound_write_wav(const char *path, const u8 *pcm, int nsamples, int rate)
{
    FILE *f;
    u32 datalen;

    if (path == NULL || pcm == NULL || nsamples < 0 || rate <= 0)
        return OSB_EBADARG;

    datalen = (u32)nsamples;

    f = fopen(path, "wb");
    if (f == NULL)
        return OSB_EIO;

    /* RIFF / WAVE header, 8-bit mono PCM */
    fwrite("RIFF", 1, 4, f);
    put_u32le(f, 36 + datalen);
    fwrite("WAVE", 1, 4, f);
    fwrite("fmt ", 1, 4, f);
    put_u32le(f, 16);        /* fmt chunk size            */
    put_u16le(f, 1);         /* PCM                       */
    put_u16le(f, 1);         /* mono                      */
    put_u32le(f, (u32)rate); /* sample rate               */
    put_u32le(f, (u32)rate); /* byte rate = rate * 1 * 1  */
    put_u16le(f, 1);         /* block align               */
    put_u16le(f, 8);         /* bits per sample           */
    fwrite("data", 1, 4, f);
    put_u32le(f, datalen);
    fwrite(pcm, 1, (size_t)nsamples, f);

    fclose(f);
    return OSB_OK;
}

void sound_bell(void)
{
    fputc('\a', stdout);
    fflush(stdout);
}

int osb_print_file(const char *path)
{
    struct sound *s;
    u8 buf[SOUND_MAX_SAMPLES];
    int n, total = 0;

    if (path == NULL || path[0] == '\0')
        return OSB_EBADARG;

    s = sound_create();
    if (s == NULL)
        return OSB_ENOMEM;

    printf("printer: printing %s ...\n", path);

    /* ready chirp -> a banner line -> the body -> a feed -> the done-bell.
     * Each stage is appended at the buffer's tail, the way a real print job
     * is a stream of head movements rather than one held tone. */
    n = sound_printer(s, PRINTER_READY, buf + total,
                      (int)sizeof(buf) - total, PRINTER_CPS_DEFAULT);
    if (n > 0)
        total += n;

    n = sound_printer(s, PRINTER_LINE, buf + total,
                      (int)sizeof(buf) - total, 140); /* the banner */
    if (n > 0)
        total += n;

    n = sound_printer(s, PRINTER_LINE, buf + total,
                      (int)sizeof(buf) - total, PRINTER_CPS_DEFAULT);
    if (n > 0)
        total += n;

    n = sound_printer(s, PRINTER_FEED, buf + total,
                      (int)sizeof(buf) - total, PRINTER_CPS_DEFAULT);
    if (n > 0)
        total += n;

    n = sound_printer(s, PRINTER_BELL, buf + total,
                      (int)sizeof(buf) - total, PRINTER_CPS_DEFAULT);
    if (n > 0)
        total += n;

    sound_off(s);
    sound_destroy(s);

    sound_bell(); /* audible even without an audio device */
    printf("printer: %d sample(s) sent to the printer\n", total);
    return OSB_OK;
}

void sound_describe(int event, double freq_hz, int ms)
{
    const char *name;

    if (event < 0)
    {
        printf("  %-22s %7.0f Hz  %4d ms\n", "tone: 2600 Hz", freq_hz, ms);
        return;
    }

    if (event >= PRINTER_READY)
    {
        /* the printer's own vocabulary */
        switch (event)
        {
        case PRINTER_READY:
            name = "printer: ready";
            break;
        case PRINTER_DOT:
            name = "printer: character";
            break;
        case PRINTER_LINE:
            name = "printer: line";
            break;
        case PRINTER_FEED:
            name = "printer: paper feed";
            break;
        case PRINTER_BELL:
            name = "printer: done-bell";
            break;
        case PRINTER_JOB:
            name = "printer: print job";
            break;
        default:
            name = "printer";
            break;
        }
    }
    else
    {
        switch (event)
        {
        case PONG_PADDLE:
            name = "pong: paddle hit";
            break;
        case PONG_WALL:
            name = "pong: wall hit";
            break;
        case PONG_SCORE:
            name = "pong: score / miss";
            break;
        case PONG_START:
            name = "pong: serve";
            break;
        case PONG_GAME_OVER:
            name = "pong: game over";
            break;
        default:
            name = "tone";
            break;
        }
    }

    printf("  %-22s %7.0f Hz  %4d ms\n", name, freq_hz, ms);
}
